/**
 * InsightsCard — practical training insights ("not a fake chatbot").
 * Generated by training-analytics.getInsights(); an AI layer can replace that later.
 */
import { useMemo } from "react";
import { StyleSheet, View } from "react-native";
import { AppText, Card, Icon, SectionHeader } from "@/components/ui";
import { getInsights } from "@/features/workouts/lib/training-analytics";
import { useTheme } from "@/providers/ThemeProvider";
import { radius, spacing } from "@/theme";

const KIND_ICONS = {
  progression: "trending-up",
  balance: "sliders",
  recovery: "battery-charging",
  pr: "award",
  recommendation: "compass",
};

export function InsightsCard({ history }) {
  const { colors } = useTheme();
  const insights = useMemo(() => getInsights(history), [history]);

  return (
    <Card style={styles.card}>
      <SectionHeader title="Insights" subtitle="Quick notes from your recent training" />
      {insights.map((insight) => {
        const highlight = insight.kind === "recommendation";
        return (
          <View
            key={insight.id}
            style={[
              styles.row,
              { backgroundColor: highlight ? colors.accentSoft : colors.surfaceSoft },
            ]}
          >
            <Icon
              name={KIND_ICONS[insight.kind]}
              size={18}
              color={highlight ? "accentStrong" : "accent"}
            />
            <View style={styles.text}>
              <AppText variant="captionStrong" color={highlight ? "accentStrong" : "textMuted"}>
                {insight.title}
              </AppText>
              <AppText variant="small">{insight.body}</AppText>
            </View>
          </View>
        );
      })}
    </Card>
  );
}

const styles = StyleSheet.create({
  card: { gap: spacing.sm },
  row: { flexDirection: "row", gap: spacing.md, padding: spacing.md, borderRadius: radius.md },
  text: { flex: 1, gap: 2 },
});
